class SegmentTree:
    def __init__(self, data):
        self.n = len(data)
        self.tree_max = [0] * (4 * self.n)
        self.tree_sum = [0] * (4 * self.n)  # Actually not needed
        self.lazy = [0] * (4 * self.n)
        self._build(data, 0, 0, self.n - 1)

    def _build(self, data, node, start, end):
        if start == end:
            self.tree_max[node] = data[start]
        else:
            mid = (start + end) // 2
            self._build(data, 2 * node + 1, start, mid)
            self._build(data, 2 * node + 2, mid + 1, end)
            self.tree_max[node] = max(self.tree_max[2 * node + 1], self.tree_max[2 * node + 2])

    def _push(self, node, start, end):
        if self.lazy[node] != 0 and start != end:
            mid = (start + end) // 2
            left = 2 * node + 1
            right = 2 * node + 2

            self.lazy[left] += self.lazy[node]
            self.lazy[right] += self.lazy[node]

            self.tree_max[left] += self.lazy[node]
            self.tree_max[right] += self.lazy[node]

            self.lazy[node] = 0

    def update(self, l, r, x, node=0, start=0, end=-1):
        if end < 0:
            end = self.n - 1

        if l > end or r < start:
            return

        if l <= start and end <= r:
            self.lazy[node] += x
            self.tree_max[node] += x
            return

        self._push(node, start, end)
        mid = (start + end) // 2
        self.update(l, r, x, 2 * node + 1, start, mid)
        self.update(l, r, x, 2 * node + 2, mid + 1, end)
        self.tree_max[node] = max(self.tree_max[2 * node + 1], self.tree_max[2 * node + 2])

    def query_max(self, l, r, node=0, start=0, end=-1):
        if end < 0:
            end = self.n - 1

        if l > end or r < start:
            return -1

        if l <= start and end <= r:
            return self.tree_max[node]

        self._push(node, start, end)
        mid = (start + end) // 2

        left_max = self.query_max(l, r, 2 * node + 1, start, mid)
        right_max = self.query_max(l, r, 2 * node + 2, mid + 1, end)

        return max(left_max, right_max)

    def range_add(self, l, r, x):
        self.update(l, r, x)

    def range_query_max(self, l, r):
        return self.query_max(l, r)


