# Solution to the lucky days problem
# A day is "lucky" if it is:
# 1. Prime (Peter's lucky number)
# 2. Can be represented as a² + b² where a, b are positive integers (Bob's lucky number)

# From number theory: a prime p can be written as sum of two positive squares iff p=2 or p≡1(mod4)

def solution(input_str):
    l, r = map(int, input_str.strip().split())

    # Sieve of Eratosthenes to find all primes up to r
    limit = r
    is_prime = bytearray([1] * (limit + 1))
    is_prime[0] = 0  # 0 is not prime
    is_prime[1] = 0  # 1 is not prime

    # Sieve optimization
    for i in range(2, int(limit ** 0.5) + 1):
        if is_prime[i]:
            is_prime[i*i:limit+1:i] = bytearray([0] * len(is_prime[i*i:limit+1:i]))

    # Count primes in [l, r] that are either 2 or ≡ 1 (mod 4)
    count = 0
    for i in range(l, r + 1):
        if is_prime[i] == 1:
            if (i == 2) or (i % 4 == 1):
                count += 1

    return str(count) + '\n'

