def get_grundy(n, k, memo):
    if n == 0:
        return 0

    if n in memo:
        return memo[n]

    # Always can remove 1 cow
    options = {get_grundy(n - 1, k, memo)}

    # If even, can split
    if n % 2 == 0:
        x = n // 2
        if k % 2 == 1:
            # k odd: XOR of k copies of G(x) = G(x)
            options.add(get_grundy(x, k, memo))
        else:
            # k even: XOR of k copies of G(x) = 0
            options.add(0)

    # Calculate MEX
    result = 0
    while result in options:
        result += 1

    memo[n] = result
    return result

