        flow = 0
        while True:
            parent = {source: None}
            queue = [source]

            while queue:
                u = queue.pop(0)
                for w in range(nodes):
                    if w not in parent and cap[u][w] > 0:
                        parent[w] = u
                        queue.append(w)
