    friends_sorted = sorted(all_friends)
    friend_to_idx = {f: i for i, f in enumerate(friends_sorted)}
    num_friends = len(friends_sorted)

    if num_friends == 0:
        return '0'

    # Build conflict graph
    # Each segment creates conflicts between all pairs of friends in that segment
    adj_mask = [0] * num_friends

    for seg in segment_events:
        seg_indices = [friend_to_idx[f] for f in seg]
        if len(seg_indices) <= 1:
