        for u in seg_indices:
            for v in seg_indices:
                if u < v:
                    adj_mask[u] |= (1 << v)
                    adj_mask[v] |= (1 << u)

    # Find Maximum Independent Set
    memo = {}

    def solve(mask):
        if mask == 0:
            return 0

        if mask in memo:
            return memo[mask]

        # Find vertex with highest degree in current mask
