        best_vertex = -1

        for i in range(num_friends):
            if mask & (1 << i):
                degree = bin(adj_mask[i] & mask).count('1')
                if degree > best_degree:
                    best_degree = degree
                    best_vertex = i

        if best_vertex == -1:
            return 0

        # Branch: include best_vertex (exclude neighbors)
        neighbors = adj_mask[best_vertex] & mask
        res_include = 1 + solve(mask ^ neighbors ^ (1 << best_vertex))

        # Branch: exclude best_vertex
        res_exclude = solve(mask ^ (1 << best_vertex))

        result = max(res_include, res_exclude)
        memo[mask] = result
        return result

    result = solve((1 << num_friends) - 1)
    return str(result)

