import sys

def solution(input_str):
    lines = input_str.strip().split('\n')
    idx = 0

    t = int(lines[idx].strip())
    idx += 1

    results = []

    for _ in range(t):
        n_m = lines[idx].strip().split()
        n = int(n_m[0])
        m = int(n_m[1])
        idx += 1

        matrix = []
        for i in range(n):
            row = list(map(int, lines[idx].strip().split()))
            matrix.append(row)
            idx += 1

        operations = lines[idx].strip()
        idx += 1

        for op in operations:
            if op == 'R':
                # Cyclic shift columns right
                for i in range(n):
                    row = matrix[i]
                    new_row = [row[-1]] + row[:-1] if n > 1 else row
                    matrix[i] = new_row

            elif op == 'L':
                # Cyclic shift columns left
                for i in range(n):
                    row = matrix[i]
                    new_row = row[1:] + [row[0]] if n > 1 else row
                    matrix[i] = new_row

            elif op == 'D':
                # Cyclic shift rows down
                if n > 0:
                    temp = matrix[-1][:]
                    matrix = [matrix[i][:] for i in range(n-1)]
                    matrix.append(temp)

            elif op == 'U':
                # Cyclic shift rows up
                if n > 0:
                    temp = matrix[0][:]
                    matrix = [matrix[i][:] for i in range(1, n)]
                    matrix.insert(0, temp)

            elif op == 'I':
                # Inverse each row
                for i in range(n):
                    row = matrix[i]
                    inv_row = [0] * n
                    for j in range(n):
                        inv_row[row[j] - 1] = j + 1
                    matrix[i] = inv_row

            elif op == 'C':
                # Inverse each column
                for j in range(n):
                    inv_col = [0] * n
                    for i in range(n):
                        inv_col[matrix[i][j] - 1] = i + 1
                    new_col = [inv_col[i] - 1 for i in range(n)]
                    for k in range(n):
                        matrix[k][j] = new_col[k]

        # Format output
        out_lines = []
        for row in matrix:
            out_lines.append(' '.join(map(str, row)))
        results.append('\n'.join(out_lines))

    return '\n'.join(results)

