def solution(input_str):
    lines = input_str.strip().split('\n')
    q = int(lines[0])
    result = []
    idx = 1

    for _ in range(q):
        n = int(lines[idx])
        idx += 1
        if idx < len(lines):
            a = list(map(int, lines[idx].split()))
            idx += 1
        else:
            a = []

        if n == 0:
            result.append("0")
            continue

        # Find first occurrence of each distinct value
        first_occ = {}
        for i, x in enumerate(a):
            if x not in first_occ:
                first_occ[x] = i

        # Sort values and get their first positions
        sorted_values = sorted(first_occ.keys())
        pos = [first_occ[v] for v in sorted_values]

        # Find longest non-decreasing subsequence from the start (greedy)
        longest = 1
        for i in range(1, len(pos)):
            if pos[i] > pos[i - 1]:
                longest += 1
            else:
                longest = 1  # Reset chain

        distinct_count = len(first_occ)
        result.append(str(distinct_count - longest))

    return '\n'.join(result)

