class TestReportPatch:
    @classmethod
    def from_item_and_call(cls, item, call):
        from _pytest.runner import TestReport
        original = TestReport.from_item_and_call

        def patched(item, call):
            report = original.__func__(item, call)
            if call.excinfo is None or call.excinfo.outcome == 'passed':
                report = (type('TestReport', (), {
                    'when': 'call',
                    'outcome': 'passed',
                    'longrepr': None,
                    'unexcinfo': None,
                    'count_testpaths': 0
