def solution(input_str):
    """
    Find three internally-vertex-disjoint, edge-disjoint paths between two vertices.
    """
    lines = input_str.strip().split('\n')
    n, m = int(lines[0].split()[0]), int(lines[0].split()[1])

    adj = {}
    for i in range(1, m + 1):
        parts = lines[i].split()
        u, v = int(parts[0]), int(parts[1])
        if u not in adj: adj[u] = []
        if v not in adj: adj[v] = []
        adj.setdefault(u, []).append(v)
        adj.setdefault(v, []).append(u)

    if m < 3:
        return "NO\n"

    def find_paths(adj, start, end, used_edges, used_internal):
        """Find paths using flow-like approach with DFS"""
        paths = []

        def dfs(current, target, path, used_local_edges, used_local_internal):
            if current == target:
                paths.append((list(path), used_local_edges | used_edges | {f"({current},{current})"}))
                return

            if len(path) > 1000:
                return

            for neighbor in adj.get(current, []):
                edge = (min(current, neighbor), max(current, neighbor))
                if neighbor in used_internal or edge in used_local_edges or edge in used_edges:
                    continue
                if neighbor == current:
                    continue

                new_path = path + [neighbor]
                new_internal = used_local_internal | {current}
                new_edges = used_local_edges | {edge}

                dfs(neighbor, target, new_path, new_edges, new_internal)

        dfs(start, end, [start], set(), set())
        return paths

    def get_three_disjoint_paths(adj, n):
        """Try to find three disjoint paths"""
        vertices = sorted(adj.keys(), key=lambda x: len(adj[x]), reverse=True)

        for i, start in enumerate(vertices):
            for j, end in enumerate(vertices):
                if i == j:
                    continue

                # Check if they can be connected
                try:
                    used_edges_global = {}
                    found_paths = []

                    # First path
                    path1 = find_path_dfs(adj, start, end, set(), used_edges_global)
                    if path1 and len(path1) >= 2:
                        found_paths.append(path1)
                        used_edges_global.update(edges_from_path(path1))
                        used_internal = set(path1[1:-1] if len(path1) >= 2 else set())

                    # Second path
                    path2 = find_path_dfs(adj, start, end, used_edges_global, used_internal)
                    if path2 and len(path2) >= 2:
                        used_edges_global.update(edges_from_path(path2))
                        used_internal.update(path2[1:-1] if len(path2) >= 2 else set())
                        found_paths.append(path2)

                    # Third path
                    path3 = find_path_dfs(adj, start, end, used_edges_global, used_internal)
                    if path3 and len(path3) >= 2:
                        found_paths.append(path3)
                        if len(found_paths) >= 3:
                            return found_paths

                except:
                    continue

        return None

    def find_path_dfs(adj, start, end, used_edges, used_internal):
        """Find a single path from start to end avoiding used edges and internal nodes"""
        if start == end:
            return [start]

        def dfs(current, path):
            if current == end:
                return path

            for neighbor in adj.get(current, []):
                if neighbor == current:
                    continue
                edge = (min(current, neighbor), max(current, neighbor))
                internal = neighbor <= 1 or neighbor in used_internal

                if edge in used_edges and internal:
                    continue

                path = path + [neighbor]
                new_internal = set(path[-2:-1]) if len(path) >= 2 else set()
                new_internal.add(end)
                new_internal.discard(current)

                result = dfs(neighbor, path)
                if result:
                    return result

            return None

        path = dfs(start, [start])
        return path if path else None

    def edges_from_path(path):
        """Extract edges from a path"""
        edges = set()
        for i in range(len(path) - 1):
            edges.add((min(path[i], path[i+1]), max(path[i], path[i+1])))
        return edges

    paths = get_three_disjoint_paths(adj, n)

    if paths:
        result = ["YES"]
        for path in paths:
            if len(path) >= 2:
                result.append(" ".join(map(str, path)))
            else:
                result.append("NO")
        return "\n".join(result) + "\n"

    return "NO\n"

