    n, r = map(int, parts[0].split())

    # Generate all integer coordinates within distance r from origin
    points = []
    circle_points = []  # Points on the circle (exactly distance r)

    for x in range(-r, r + 1):
        for y in range(-r, r + 1):
            dist_sq = x * x + y * y
            if dist_sq <= r * r:
                points.append((x, y))
                if dist_sq == r * r:
                    circle_points.append((x, y))

    m = len(points)

    # Precompute squared distances between all pairs
    dists = [[0] * m for _ in range(m)]
    for i in range(m):
        for j in range(i + 1, m):
            dx = points[i][0] - points[j][0]
            dy = points[i][1] - points[j][1]
            d = dx * dx + dy * dy
            dists[i][j] = d
            dists[j][i] = d

    best_score = -1
    best_indices = []

    # Try all combinations of exactly n points
    # For large r, this could be slow, but n <= 8 keeps it manageable
    for indices in combinations(range(m), n):
        score = 0
        for i in range(n):
            for j in range(i + 1, n):
                score += dists[indices[i]][indices[j]]

        if score > best_score:
            best_score = score
            best_indices = indices

    # Format output
    output_lines = [str(best_score)]
    for idx in best_indices:
        output_lines.append(f"{points[idx][0]} {points[idx][1]}")

    return '\n'.join(output_lines)


