from collections import deque
import io, sys, os

def solution(input_str):
    # Parse input
    input_str = input_str.strip()
    if not input_str:
        return '-1\n'

    lines = input_str.split('\n')
    n, m = map(int, lines[0].split())

    # Build adjacency list
    adj = [[] for _ in range(n + 1)]
    for i in range(1, m + 1):
        if i < len(lines):
            u, v = map(int, lines[i].split())
            adj[u].append(v)
            adj[v].append(u)

    # Find connected components
    visited = [False] * (n + 1)
    components = []

    for i in range(1, n + 1):
        if not visited[i]:
            count = 0
            stack = [i]
            visited[i] = True
            while stack:
                node = stack.pop()
                count += 1
                for neighbor in adj[node]:
                    if not visited[neighbor]:
                        visited[neighbor] = True
                        stack.append(neighbor)
            components.append(count)

    # Generate lucky numbers up to n
    lucky_numbers = []
    queue = [4, 7]
    while queue and queue[0] <= n:
        num = queue.pop(0)
        lucky_numbers.append(num)
        queue.append(num * 10 + 4)
        queue.append(num * 10 + 7)
    lucky_numbers.sort()

    # Check if any component is already lucky
    for comp in components:
        if comp in lucky_numbers:
            return '0\n'

    # For each lucky number, find minimum components needed
    min_road_count = float('inf')

    def find_min_components(target_idx):
        target = lucky_numbers[target_idx]
        if target > n:
            return float('inf')

        # BFS to find minimum components summing to target
        visited_sums = {0}
        queue = deque([(0, 0)])  # (sum, count)

        min_count = float('inf')

        while queue:
            curr_sum, cnt = queue.popleft()

            if curr_sum > target:
                continue
            if cnt >= min_count:
                continue

            if curr_sum == target:
                min_count = cnt
                break

            for comp in components:
                new_sum = curr_sum + comp
                if new_sum <= target and new_sum not in visited_sums:
                    visited_sums.add(new_sum)
                    queue.append((new_sum, cnt + 1))

        return min_count

    # Try each lucky number
    for idx, lucky in enumerate(lucky_numbers):
        if lucky > n:
            continue

        min_k = find_min_components(idx)
        if min_k < float('inf'):
            min_road_count = min(min_road_count, min_k - 1)

    if min_road_count == float('inf'):
        return '-1\n'

    return str(min_road_count) + '\n'

