def solution(input_str):
    lines = input_str.strip().split('\n')
    n, s = map(int, lines[0].split())
    buildings = []
    for i in range(n):
        v, c = map(int, lines[1 + i].split())
        buildings.append((v, c))

    def can_achieve(T):
        current_money = 0
        current_rate = 0

        # Find buildings with cost 0 to start
        for v, c in buildings:
            if c == 0:
                current_rate = v
                break

        # If still 0 (unlikely but handle it), clicking gives 1 cookie/second
        if current_rate == 0 and s > 0:
            current_rate = 1

        # Simulate T seconds
        for _ in range(T):
            current_money += current_rate

            # Find the best building we can afford
            best_v = current_rate
            for v, c in buildings:
                if c <= current_money and v > best_v:
                    best_v = v

            # Buy and switch to best building
            for v, c in buildings:
                if c <= current_money and v > current_rate:
                    current_money -= c
                    current_rate = v
                    break

        return current_money >= s

    # Binary search for minimum T
    low = 0
    high = s  # Worst case: click at rate 1 for S seconds

    while low < high:
        mid = (low + high) // 2
        if can_achieve(mid):
            high = mid
        else:
            low = mid + 1

    return str(low)
